      let iconNumber = 0;
      function vectorIcon(name, width, height = width, className = 'ui-icon') {
        const asset = iconBank[name];
        if (!asset) return '';
        const [attrs, paths] = asset;
        const idPrefix = 'ui-icon-' + (++iconNumber) + '-';
        const body = paths.replace(/\bid="([^"]+)"/g, (_, id) => 'id="' + idPrefix + id + '"')
          .replace(/url\(#([^)]+)\)/g, (_, id) => 'url(#' + idPrefix + id + ')')
          .replace(/\bhref="#([^"]+)"/g, (_, id) => 'href="#' + idPrefix + id + '"');
        return `<svg class="${className}" width="${width}" height="${height}" aria-hidden="true" focusable="false" ${attrs}>${body}</svg>`;
      }
